versions.variantCss:
.wemd-numbered-heading[data-variant="bytedance-heading-numbered"] {
  margin: 32px 0 20px 0;
  padding: 0;
}
.wemd-numbered-heading[data-variant="bytedance-heading-numbered"] .wemd-component-body {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
}
.wemd-numbered-heading[data-variant="bytedance-heading-numbered"] .wemd-component-body .wemd-child-1 {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 48px;
  height: 40px;
  padding: 0 12px;
  background: linear-gradient(135deg, var(--wemd-primary), var(--wemd-primary-dark));
  color: #ffffff;
  font-size: 20px;
  font-weight: 700;
  border-radius: 8px;
  margin-right: 16px;
  letter-spacing: 0.5px;
}
.wemd-numbered-heading[data-variant="bytedance-heading-numbered"] .wemd-component-body .wemd-child-2 {
  color: var(--wemd-text-strong);
  font-size: 24px;
  font-weight: 700;
  line-height: 1.3;
  margin: 0;
}
